import {PHASES,DAYS,DRAW_ORDER,clamp,interval} from './model.mjs';
const PHOTO='assets/swallow-roost-dawn-v01.png';
let svg,refs={},ready=false,latest=null,timeline=null,toy=null,author=null;
const camera={zoom:1};
const $=id=>refs[id]??(refs[id]=svg.querySelector(`#${id}`));
const n=v=>Math.round(v*10000)/10000;
const fmt=v=>Number(v).toLocaleString('en-US',{maximumFractionDigits:1});
function opacity(id,v){const e=$(id);e.style.opacity=n(v);e.style.visibility=v>.0001?'visible':'hidden';}
function text(id,v){const e=$(id);if(e.textContent!==String(v))e.textContent=String(v);}
function path(points){return points.map((p,i)=>`${i?'L':'M'}${n(p[0])} ${n(p[1])}`).join(' ');}
function daysMarkup(){return DAYS.map((d,i)=>`<g id="day-${d.id}" transform="translate(${80+i*385} 214)"><rect width="345" height="405" rx="4" class="day-paper"/><text x="27" y="55" class="day-id">${d.id}日</text><text x="27" y="112" class="copy muted">電腦預估</text><text x="27" y="185" class="number">${d.g}</text><g id="q-${d.id}"><text x="27" y="253" class="copy muted">抽樣機率</text><text x="27" y="325" class="number accent">${d.q*100}%</text></g></g>`).join('');}
function drawMarkup(){return DRAW_ORDER.map((id,i)=>{const d=DAYS.find(x=>x.id===id);return `<g id="draw-${i}" transform="translate(${85+i*385} 290)"><rect width="335" height="345" rx="4" class="day-paper"/><text x="24" y="48" class="copy muted">第${i+1}次抽取</text><text x="24" y="128" class="number">${id}日</text><text x="24" y="188" class="copy">電腦 ${d.g}　人工 ${d.f}</text><text x="24" y="246" class="copy accent">機率 ${d.q*100}%</text>${i===2?'<text x="24" y="305" class="copy warm">沿用第一次的覆核</text>':''}</g>`;}).join('');}
function markup(){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 900" class="discount-scene" role="img" aria-label="燕群雷達與DISCount機率抽樣動畫">
<style>
.discount-scene{--p:#f3f0e8;--ink:#26332f;--muted:#5b6765;--line:#a6aea7;--accent:#287e94;--warm:#9a592e;--tile:#e8e5dc;font-family:var(--font-sans,'PingFang TC',sans-serif);background:var(--p)}
html[data-theme=dark] .discount-scene{--p:#1b1e1f;--ink:#f0eee7;--muted:#b9bdbb;--line:#667572;--accent:#83c9d3;--warm:#eac17d;--tile:#282e30}
.discount-scene text{fill:var(--ink)}.paper{fill:var(--p)}.title{font:500 43px var(--font-serif,'Songti TC',serif)}.big{font:500 49px var(--font-serif,'Songti TC',serif)}.number{font:500 72px var(--font-serif,'Songti TC',serif);font-variant-numeric:tabular-nums}.large-number{font:500 126px var(--font-serif,'Songti TC',serif)}.day-id{font:500 39px var(--font-serif,'Songti TC',serif)}.label{font-size:30px;font-weight:500}.copy{font-size:26px}.small{font-size:20px}.muted{fill:var(--muted)!important}.accent{fill:var(--accent)!important}.warm{fill:var(--warm)!important}.line{fill:none;stroke:var(--line);stroke-width:1.5}.layer{visibility:hidden;opacity:0}.day-paper{fill:var(--tile);stroke:var(--line);stroke-width:1}.chip{fill:var(--p);opacity:.95}.curve{fill:none;stroke-width:3;stroke-linejoin:round;stroke-linecap:round}.radar-line{fill:none;stroke:var(--accent);stroke-width:2}.ref-line{stroke:var(--warm)}.detection-line{stroke:var(--accent)}
</style><defs><clipPath id="habitat-clip"><rect y="126" width="1600" height="725"/></clipPath><clipPath id="curve-clip"><rect id="curve-reveal" x="110" y="275" width="1375" height="375"/></clipPath></defs><rect class="paper" width="1600" height="900"/>
<g id="habitat" class="layer" clip-path="url(#habitat-clip)"><g id="habitat-camera"><image href="${PHOTO}" width="1600" height="900" preserveAspectRatio="xMidYMid slice"/></g><rect class="chip" x="925" y="188" width="610" height="231" rx="3"/><text class="big" x="959" y="260">夜裡聚在一起，</text><text class="big" x="959" y="329">清晨向外飛散。</text><text class="copy" x="960" y="385">五大湖周邊的燕科鳥類</text></g>
<g id="radar" class="layer"><g transform="translate(440 475)"><circle r="290" fill="var(--tile)"/><circle r="95" class="radar-line" opacity=".25"/><circle r="190" class="radar-line" opacity=".25"/><circle r="280" class="radar-line" opacity=".4"/><path d="M-280 0H280M0-280V280" class="radar-line" opacity=".3"/><path d="M-190 -35Q-115 5 -165 90T-170 210M180 -200Q110 -110 200 -65T160 185" class="line" opacity=".45"/><g id="echo-ring"><path d="M15 -118A120 120 0 0 1 111 47M97 71A120 120 0 0 1 -60 104M-86 84A120 120 0 0 1 -116 -31M-101 -65A120 120 0 0 1 -18 -119" fill="none" stroke="var(--accent)" stroke-width="12" stroke-linecap="round" opacity=".7"/></g><circle r="7" fill="var(--warm)"/></g><text class="copy muted" x="440" y="817" text-anchor="middle">訊號形狀示意，非原始雷達掃描</text><text class="big" x="855" y="276">向外擴張的環</text><text class="copy" x="858" y="363">連續掃描 → 找出並追蹤鳥群訊號</text><text class="copy" x="858" y="428">軌跡內的反射率 → 換算計數</text><path class="line" d="M858 483H1492"/><text class="label warm" x="858" y="556">一個亮點 ≠ 一隻鳥</text><text class="copy" x="858" y="626">一天內有多次掃描。</text><text class="copy" x="858" y="676">抽樣覆核時，以「一天」為單位。</text></g>
<g id="archive" class="layer"><text class="label" x="83" y="205">KBUF雷達站・2010年・作者公開資料</text><g><path d="M110 275V650H1485" class="line"/><g id="archive-ticks"/><g clip-path="url(#curve-clip)"><path id="detector-curve" class="curve detection-line"/><path id="reference-curve" class="curve ref-line"/></g></g><path class="detection-line" d="M111 721H167" stroke-width="4"/><text class="copy" x="181" y="729">自動計數</text><path class="ref-line" d="M431 721H487" stroke-width="4"/><text class="copy" x="501" y="729">人工覆核後的參考計數</text><text class="copy muted" x="1485" y="695" text-anchor="end">季節內日序 1–92</text><text class="small muted" x="110" y="260">每日計數（萬）</text><text class="label" x="83" y="812">12座雷達站 × 約20年，每個站點與年份分開估計。</text></g>
<g id="proposal" class="layer">${daysMarkup()}<text class="label" x="82" y="700">電腦總量 100</text><text class="label" x="688" y="700">每天的機率 ＝ 當天預估 ÷ 100</text><text class="copy" x="82" y="775">預估較多，較容易被抽到；預估較少，也保有機會。</text></g>
<g id="screen" class="layer"><text class="label" x="85" y="218">一次可能的抽樣：D → B → D → C</text>${drawMarkup()}<text class="big" x="85" y="744" id="draw-summary">等待抽取</text><text class="copy muted" x="85" y="803">重抽同一天，保留這次抽取，但不用重做人工覆核。</text></g>
<g id="estimate" class="layer"><text class="label" x="83" y="214">先看每次的「人工 ÷ 電腦」</text>${['44 ÷ 40','18 ÷ 20','44 ÷ 40','36 ÷ 30'].map((f,i)=>`<g transform="translate(${86+i*385} 296)"><text class="copy muted">${DRAW_ORDER[i]}日</text><text class="big" y="74">${f}</text><text class="big accent" y="151">${[1.1,.9,1.1,1.2][i].toFixed(1)}</text></g>`).join('')}<path class="line" d="M85 492H1515"/><g id="estimate-answer"><text class="copy" x="85" y="562">四次比值的平均</text><text class="number" x="85" y="651">1.075</text><text class="big" x="397" y="637">× 100 ＝</text><text class="large-number accent" x="770" y="657">107.5</text><text class="copy muted" x="1140" y="648">估計總量</text></g><g id="truth-answer"><text class="label warm" x="85" y="760">四天全部覆核後的總量是110。</text><text class="copy" x="85" y="811">這一次估計略低；抽樣沒有保證每次都剛好算對。</text></g></g>
<g id="variation" class="layer"><text class="label" x="85" y="214">相同的四天，每次抽四次</text><path d="M110 287V655H1485" class="line"/><g id="distribution-ticks"/><g id="distribution-bars"/><path id="truth-line" d="M0 280V655" stroke="var(--warm)" stroke-width="2" stroke-dasharray="7 7"/><text class="copy warm" id="truth-line-label" y="272" text-anchor="middle">110</text><text class="small muted" x="110" y="266">結果的機率</text><text class="small muted" x="1485" y="713" text-anchor="end">估計總量</text><rect x="110" y="730" width="28" height="17" fill="var(--accent)" opacity=".85"/><text class="copy" x="154" y="751">依電腦計數抽樣</text><rect x="566" y="730" width="28" height="17" fill="var(--line)" opacity=".6"/><text class="copy" x="610" y="751">每天等機率抽樣</text><text class="label" x="85" y="817">按機率加權，兩者的平均估計都是110。</text></g>
<g id="results" class="layer"><text class="label" x="84" y="207">論文的鳥群實驗・平均1000次試驗</text><text class="big" x="84" y="304">達平均相對誤差20%時</text><text class="copy" x="84" y="390">均勻隨機抽樣</text><rect x="84" y="420" width="1380" height="49" fill="var(--line)" opacity=".45"/><text class="copy" x="84" y="533">DISCount</text><rect x="84" y="563" width="460" height="49" fill="var(--accent)"/><text class="big accent" x="589" y="607">約需三分之一的覆核抽樣日</text><text class="small muted" x="84" y="661">覆核日數比例示意，並非圖上讀出的精確樣本數。</text><g id="conclusion"><text class="big" x="84" y="749">電腦幫忙安排覆核，統計方法估整批總量。</text><text class="copy" x="84" y="812">仍有估計誤差；原研究的95%信賴區間，也未達95%的涵蓋率。</text></g></g>
<rect class="paper" width="1600" height="126"/><text id="headline" class="title" x="52" y="63"/><text id="subtitle" class="copy muted" x="54" y="105"/><rect class="paper" y="851" width="1600" height="49"/><text id="disclosure" class="small muted" x="32" y="883"/><text id="stage-time" class="small muted" x="1566" y="883" text-anchor="end"/></svg>`;}
function archiveChart(){
 const values=[...author.detector,...author.human_reference],max=Math.ceil(Math.max(...values)/10000)*10000;
 const X=i=>110+i*1375/(author.detector.length-1),Y=v=>650-v/max*350;
 $('detector-curve').setAttribute('d',path(author.detector.map((v,i)=>[X(i),Y(v)])));
 $('reference-curve').setAttribute('d',path(author.human_reference.map((v,i)=>[X(i),Y(v)])));
 $('archive-ticks').innerHTML=[0,1,2,3].map(i=>{const v=max*i/3,y=Y(v);return `<path class="line" opacity=".3" d="M110 ${y}H1485"/><text x="96" y="${y+7}" text-anchor="end" class="small muted">${fmt(v/10000)}</text>`;}).join('');
}
function distributionChart(){
 const X=v=>110+(v-40)/145*1375,all=[...toy.histograms.uniform,...toy.histograms.importance],max=Math.max(...all.map(d=>d.probability))*1.15,Y=v=>655-v/max*350;
 let html='';for(const [kind,color,alpha] of [['uniform','var(--line)',.5],['importance','var(--accent)',.9]])for(const b of toy.histograms[kind]){if(b.probability===0)continue;const x=X(b.lower),w=X(b.upper)-x;html+=`<rect data-distribution="${kind}" x="${n(x+1)}" y="${n(Y(b.probability))}" width="${n(Math.max(1,w-2))}" height="${n(655-Y(b.probability))}" fill="${color}" opacity="${alpha}"/>`;}
 $('distribution-bars').innerHTML=html;$('truth-line').setAttribute('transform',`translate(${n(X(110))} 0)`);$('truth-line-label').setAttribute('x',X(110));
 $('distribution-ticks').innerHTML=[50,75,100,125,150,175].map(v=>`<text class="small muted" x="${X(v)}" y="687" text-anchor="middle">${v}</text>`).join('')+[0,.1,.2,.3].filter(v=>v<=max).map(v=>`<text class="small muted" x="95" y="${Y(v)+6}" text-anchor="end">${Math.round(v*100)}%</text>`).join('');
}
function preload(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>i.decode().then(resolve,resolve);i.onerror=()=>reject(new Error('棲地圖片未載入。'));i.src=src;});}
export async function initScene(element){ready=false;refs={};timeline?.kill();camera.zoom=1;element.innerHTML=markup();svg=element.querySelector('svg');svg.style.cssText='display:block;width:100%;height:100%';const data=await Promise.all(['data/sampling-teaching-v01.json','data/author-kbuf-2010-v01.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw new Error('計數資料未載入。');return r.json();}));[toy,author]=data;archiveChart();distributionChart();if(!window.gsap)throw new Error('動畫序列未載入。');timeline=gsap.timeline({paused:true}).to(camera,{zoom:1.025,duration:14,ease:'none'},0);await preload(PHOTO);ready=true;}
export function renderScene(s){if(!ready)return;latest=s;timeline.time(s.time,false);const p=PHASES[s.phase],edge=Math.min(s.phase===0?1:interval(s.time,p.start,p.start+.35),s.phase===7?1:interval(p.end-s.time,0,.28));
 for(const [i,id] of ['habitat','radar','archive','proposal','screen','estimate','variation','results'].entries())opacity(id,s.phase===i?edge:0);
 const z=s.reducedMotion?1:camera.zoom;$('habitat-camera').setAttribute('transform',`translate(${n(800*(1-z))} ${n(450*(1-z))}) scale(${n(z)})`);
 const ring=s.reducedMotion?1.4:.65+1.25*interval(s.time,14,28);$('echo-ring').setAttribute('transform',`scale(${n(ring)})`);
 const reveal=s.reducedMotion?1:interval(s.time,30,37);$('curve-reveal').setAttribute('width',n(1375*reveal));
 for(const d of DAYS)opacity(`q-${d.id}`,s.proposalVisible?interval(s.time,49,50):0);
 for(let i=0;i<4;i++)opacity(`draw-${i}`,s.drawCount>i?1:0);
 text('draw-summary',s.drawCount?`${s.drawCount}次抽取，${s.uniqueDayCount}個不同日子`:'等待抽取');
 opacity('estimate-answer',s.estimateVisible?interval(s.time,85,86):0);opacity('truth-answer',s.truthVisible?interval(s.time,93,94):0);
 opacity('conclusion',s.conclusionVisible?interval(s.time,122,123):0);
 const subtitles=['清晨離開集體棲地，雷達也能留下線索。','由訊號換算計數；覆核的抽樣單位是「一天」。','同一批資料：自動計數與人工覆核後的參考計數。','四天的教學範例・先設定每天被抽到的機率。','教學範例・依已知機率抽樣，可重複抽到同一天。','教學範例・整批電腦總量 × 抽中日子的平均修正比值。','教學範例・完整列舉四次抽取的256種順序。','實際研究結果・不是前面四天範例的結果。'];
 const notes=['AI生成棲地情境，非研究現場照片。','環狀訊號為概念示意；人工參考量仍由雷達資料換算。','來源：作者DISCount程式庫・KBUF 2010・日序未附日曆日期。','數字為教學用計數單位；每一天都有非零抽樣機率。','D日的人工覆核沿用；估計式仍計四次抽取，不是只留三筆。','單一集合的DISCount估計；107.5不是實際鳥群數量。','柱形為機率，非觀測頻率；兩者期望值同為110，不代表單次必定算對。','Perez et al. (2024), §5・累積計數不等於不重複鳥隻總數。'];
 text('headline',p.title);text('subtitle',subtitles[s.phase]);text('disclosure',notes[s.phase]);text('stage-time',`${String(Math.floor(s.time/60)).padStart(2,'0')}:${String(Math.floor(s.time%60)).padStart(2,'0')}`);
}
export function getSceneState(){return {ready,time:latest?.time??0,phaseId:latest?.phaseId??null,renderedZoom:latest?.reducedMotion?1:camera.zoom,drawCount:latest?.drawCount??0,uniqueDayCount:latest?.uniqueDayCount??0,estimate:107.5,knownToyTotal:110,distributionKind:'exact-enumeration-4-power-4',modelInferenceRun:false,authorDataRows:author?.detector?.length??0,samplingUnit:'day',humanReferenceKind:'screened-radar-derived',samplingWithReplacement:true,conclusionVisible:latest?.conclusionVisible??false,hasAudio:false};}
